@dataclass
class YearInfo:
    """Facts about a Hebrew year."""

    # The year, for example 5785.
    year: int
    # Whether it has 13 months.
    is_leap: bool
    # The number of days, 353 to 385.
    days: int
    # Whether Cheshvan and Kislev are long or short.
    length: YearLength
    # Whether Cheshvan has 30 days.
    is_cheshvan_long: bool
    # Whether Kislev has 29 days.
    is_kislev_short: bool
    # The months in order, from Tishrei.
    months: List[HebrewMonth]


def _write_YearInfo(_w: _Writer, value: YearInfo) -> None:
    _w.write_i32(value.year)
    _w.write_bool(value.is_leap)
    _w.write_i32(value.days)
    _w.write_i32(value.length)
    _w.write_bool(value.is_cheshvan_long)
    _w.write_bool(value.is_kislev_short)
    _write_list_HebrewMonth(_w, value.months)


def _read_YearInfo(_r: _Reader) -> YearInfo:
    return YearInfo(
        year=_r.read_i32(),
        is_leap=_r.read_bool(),
        days=_r.read_i32(),
        length=_r.read_enum(YearLength),
        is_cheshvan_long=_r.read_bool(),
        is_kislev_short=_r.read_bool(),
        months=_read_list_HebrewMonth(_r),
    )


