class TehillimUnit:
    """A day's portion of Tehillim."""

    class Tag(IntEnum):
        # Whole chapters, `start` to `end` inclusive.
        Psalms = 0
        # Part of one long chapter (119, split over two days).
        PsalmVerses = 1

    Psalms: Type[TehillimUnitPsalms]
    PsalmVerses: Type[TehillimUnitPsalmVerses]
    TAG: TehillimUnit.Tag

    @property
    def tag(self) -> TehillimUnit.Tag:
        """The discriminant of this value's active variant."""
        return type(self).TAG


@dataclass
class TehillimUnitPsalms(TehillimUnit):
    """Whole chapters, `start` to `end` inclusive."""

    TAG = TehillimUnit.Tag.Psalms

    # The first chapter.
    start: int
    # The last chapter.
    end: int


@dataclass
class TehillimUnitPsalmVerses(TehillimUnit):
    """Part of one long chapter (119, split over two days)."""

    TAG = TehillimUnit.Tag.PsalmVerses

    # The chapter.
    psalm: int
    # The first verse.
    start_verse: int
    # The last verse.
    end_verse: int


TehillimUnit.Psalms = TehillimUnitPsalms
TehillimUnit.PsalmVerses = TehillimUnitPsalmVerses


def _write_TehillimUnit(_w: _Writer, value: TehillimUnit) -> None:
    if isinstance(value, TehillimUnitPsalms):
        _w.write_i32(0)
        _w.write_i32(value.start)
        _w.write_i32(value.end)
        return
    if isinstance(value, TehillimUnitPsalmVerses):
        _w.write_i32(1)
        _w.write_i32(value.psalm)
        _w.write_i32(value.start_verse)
        _w.write_i32(value.end_verse)
        return
    raise TypeError(f"expected a TehillimUnit variant, got {type(value).__name__}")


def _read_TehillimUnit(_r: _Reader) -> TehillimUnit:
    tag = _r.read_i32()
    if tag == 0:
        return TehillimUnitPsalms(
            start=_r.read_i32(),
            end=_r.read_i32(),
        )
    if tag == 1:
        return TehillimUnitPsalmVerses(
            psalm=_r.read_i32(),
            start_verse=_r.read_i32(),
            end_verse=_r.read_i32(),
        )
    raise _malformed(f"unknown TehillimUnit tag {tag}")


